  // ── Lembranças (memorial) ───────────────────────────────────────────────
  "Lembranças": ["Memories", "Recuerdos", "Erinnerungen", "Souvenirs"],
  "Para os que já partiram, mas nunca nos deixam": ["For those who left us, but never really go", "Para los que ya partieron, pero nunca nos dejan", "Für die, die gegangen sind, uns aber nie verlassen", "Pour ceux qui sont partis, mais ne nous quittent jamais"],
  "Ainda não há lembranças": ["No memories yet", "Todavía no hay recuerdos", "Noch keine Erinnerungen", "Pas encore de souvenirs"],
  "Este é um cantinho para recordar os animais que já partiram. Junte as fotos, um vídeo e umas palavras de despedida.": ["This is a little corner to remember the pets who have passed. Add photos, a video and a few words of farewell.", "Este es un rinconcito para recordar a los animales que se fueron. Añada fotos, un vídeo y unas palabras de despedida.", "Dies ist ein kleiner Ort, um an verstorbene Tiere zu erinnern. Fügen Sie Fotos, ein Video und Abschiedsworte hinzu.", "Voici un petit coin pour se souvenir des animaux partis. Ajoutez des photos, une vidéo et quelques mots d'adieu."],
  "Nova lembrança": ["New memory", "Nuevo recuerdo", "Neue Erinnerung", "Nouveau souvenir"],
  "Criar lembrança": ["Create memory", "Crear recuerdo", "Erinnerung erstellen", "Créer un souvenir"],
  "Publicar lembrança": ["Publish memory", "Publicar recuerdo", "Erinnerung veröffentlichen", "Publier le souvenir"],
  "Apagar lembrança": ["Delete memory", "Borrar recuerdo", "Erinnerung löschen", "Supprimer le souvenir"],
  "Foto da lembrança": ["Memory photo", "Foto del recuerdo", "Foto der Erinnerung", "Photo du souvenir"],
  "Até 4 fotos. A primeira fica como foto principal.": ["Up to 4 photos. The first one is the main photo.", "Hasta 4 fotos. La primera será la principal.", "Bis zu 4 Fotos. Das erste ist das Hauptfoto.", "Jusqu'à 4 photos. La première sera la photo principale."],
  "Pode juntar até 4 fotos.": ["You can add up to 4 photos.", "Puede añadir hasta 4 fotos.", "Sie können bis zu 4 Fotos hinzufügen.", "Vous pouvez ajouter jusqu'à 4 photos."],
  "Nome do seu animal": ["Your pet's name", "Nombre de su animal", "Name Ihres Tieres", "Nom de votre animal"],
  "Escreva o nome do seu animal.": ["Please write your pet's name.", "Escriba el nombre de su animal.", "Bitte geben Sie den Namen Ihres Tieres ein.", "Écrivez le nom de votre animal."],
  "Nasceu em (opcional)": ["Born on (optional)", "Nació el (opcional)", "Geboren am (optional)", "Né le (facultatif)"],
  "Partiu em (opcional)": ["Passed away on (optional)", "Se fue el (opcional)", "Gestorben am (optional)", "Parti le (facultatif)"],
  "Umas palavras de despedida...": ["A few words of farewell...", "Unas palabras de despedida...", "Ein paar Abschiedsworte...", "Quelques mots d'adieu..."],
  "Link de um vídeo (opcional)": ["Video link (optional)", "Enlace de un vídeo (opcional)", "Video-Link (optional)", "Lien d'une vidéo (facultatif)"],
  "Para vídeos, cole aqui o link do YouTube ou do Google Fotos. Vídeos guardados na app ficariam demasiado pesados.": ["For videos, paste a YouTube or Google Photos link here. Videos stored in the app would be far too heavy.", "Para vídeos, pegue aquí el enlace de YouTube o de Google Fotos. Los vídeos guardados en la app serían demasiado pesados.", "Fügen Sie für Videos einen YouTube- oder Google-Fotos-Link ein. In der App gespeicherte Videos wären viel zu groß.", "Pour les vidéos, collez ici un lien YouTube ou Google Photos. Les vidéos stockées dans l'app seraient trop lourdes."],
  "Ver vídeo": ["Watch video", "Ver vídeo", "Video ansehen", "Voir la vidéo"],
  "Não foi possível abrir o vídeo.": ["We couldn't open the video.", "No se pudo abrir el vídeo.", "Das Video konnte nicht geöffnet werden.", "Impossible d'ouvrir la vidéo."],
  "Acender vela": ["Light a candle", "Encender una vela", "Kerze anzünden", "Allumer une bougie"],
  "Mensagens": ["Messages", "Mensajes", "Nachrichten", "Messages"],
  "Escreva uma mensagem...": ["Write a message...", "Escriba un mensaje...", "Schreiben Sie eine Nachricht...", "Écrivez un message..."],
  "Ainda não há mensagens. Deixe umas palavras de carinho.": ["No messages yet. Leave a few kind words.", "Todavía no hay mensajes. Deje unas palabras de cariño.", "Noch keine Nachrichten. Hinterlassen Sie ein paar liebe Worte.", "Pas encore de messages. Laissez quelques mots affectueux."],
  "Não foi possível enviar.": ["We couldn't send it.", "No se pudo enviar.", "Senden nicht möglich.", "Impossible d'envoyer."],
  "Publicado por": ["Published by", "Publicado por", "Veröffentlicht von", "Publié par"],
  "Utilizador": ["User", "Usuario", "Benutzer", "Utilisateur"],
  "Tem a certeza? Não dá para voltar atrás.": ["Are you sure? This can't be undone.", "¿Está seguro? No se puede deshacer.", "Sind Sie sicher? Das lässt sich nicht rückgängig machen.", "Êtes-vous sûr ? C'est irréversible."],
  "Cancelar": ["Cancel", "Cancelar", "Abbrechen", "Annuler"],
  "Ave": ["Bird", "Ave", "Vogel", "Oiseau"],
  // ── Agenda (calendário) ─────────────────────────────────────────────────
  "Agenda": ["Diary", "Agenda", "Kalender", "Agenda"],
  "Tudo o que tem marcado, mês a mês": ["Everything you have booked, month by month", "Todo lo que tiene agendado, mes a mes", "Alles, was ansteht, Monat für Monat", "Tout ce qui est prévu, mois par mois"],
  "Nada marcado para este dia.": ["Nothing booked for this day.", "Nada agendado para este día.", "Für diesen Tag ist nichts eingetragen.", "Rien de prévu ce jour-là."],
  "Não foi possível carregar a agenda.": ["We couldn't load the diary.", "No se pudo cargar la agenda.", "Der Kalender konnte nicht geladen werden.", "Impossible de charger l'agenda."],
  "Marcar consulta": ["Book an appointment", "Reservar cita", "Termin eintragen", "Prendre rendez-vous"],
